system.text:
Today's date: Sunday, 2027-01-10.
Your name: 小满.
Available functions:
[
  {
    "name": "draft_factory_day_plan",
    "description": "Drafts a same-day sequence around a work obligation and personal plans. Use it when someone asks for help arranging work, a meal, and an afternoon activity. Do not use it to submit measurements, notify customers, or book facilities. It returns a proposed plan and does not change factory operations.",
    "input_schema": {
      "type": "object",
      "properties": {
        "afternoon_activity": {
          "type": "string",
          "enum": [
            "river_fishing",
            "park_walk",
            "home_rest",
            "indoor_play"
          ],
          "description": "The kind of personal activity to place in the afternoon."
        },
        "lunch_start": {
          "type": "string",
          "pattern": "^(?:[01]\\d|2[0-3]):[0-5]\\d$",
          "description": "The proposed local start time for the meal, in 24-hour HH:MM format. Format: 24-hour time in HH:MM format."
        },
        "work_deadline": {
          "type": "string",
          "pattern": "^(?:[01]\\d|2[0-3]):[0-5]\\d$",
          "description": "The time by which the work obligation is due, in 24-hour HH:MM format. Format: 24-hour time in HH:MM format."
        },
        "work_item": {
          "type": "string",
          "enum": [
            "moisture_result",
            "shipment_review",
            "inventory_check"
          ],
          "description": "The kind of work obligation that anchors the schedule."
        }
      },
      "required": [
        "afternoon_activity",
        "lunch_start",
        "work_deadline",
        "work_item"
      ]
    }
  },
  {
    "name": "send_customer_update",
    "description": "Sends a customer-facing update about a shipment or quality check. Use it when someone requests transmission of a customer-facing status update. Do not use it to draft an internal schedule or to perform a quality check. It transmits the selected update category at the specified local time.",
    "input_schema": {
      "type": "object",
      "properties": {
        "send_time": {
          "type": "string",
          "pattern": "^(?:[01]\\d|2[0-3]):[0-5]\\d$",
          "description": "The local send time in 24-hour HH:MM format. Format: 24-hour time in HH:MM format."
        },
        "update_type": {
          "type": "string",
          "enum": [
            "testing_status",
            "shipment_delay",
            "quality_result"
          ],
          "description": "The category of customer-facing status message to send."
        }
      },
      "required": [
        "send_time",
        "update_type"
      ]
    }
  },
  {
    "name": "order_lunch_delivery",
    "description": "Orders a lunch delivery to the user's desk or meeting room. Use it when someone asks to order lunch or have a meal brought in. Do not use it for drinks, snacks or catering for a large event. Only one meal from the listed menu can be ordered per call.",
    "input_schema": {
      "type": "object",
      "properties": {
        "meal": {
          "type": "string",
          "enum": [
            "noodles",
            "rice_bowl",
            "sandwich",
            "salad",
            "dumplings"
          ],
          "description": "Meal to order from the lunch menu."
        }
      },
      "required": [
        "meal"
      ]
    }
  },
  {
    "name": "get_current_time",
    "description": "Reads the current local clock time. Use it when someone asks what time it is right now. Do not use it to set a timer or an alarm, or to look up when a future event starts. It takes no arguments and changes nothing.",
    "input_schema": {
      "type": "object",
      "properties": {},
      "required": []
    }
  },
  {
    "name": "get_weather",
    "description": "Looks up the local weather forecast for the user's current location. Use it when someone asks what the weather will be like, such as whether it will rain or how warm it will get. Do not use it for indoor temperature control or to ask for the clock time. It only reports a forecast and changes nothing.",
    "input_schema": {
      "type": "object",
      "properties": {
        "day": {
          "type": "string",
          "enum": [
            "today",
            "tomorrow"
          ],
          "description": "Which day the forecast is for, relative to the current date."
        }
      },
      "required": [
        "day"
      ]
    }
  }
]
